-- 20260922_nca_ecc_arabic.sql
-- Official Arabic text of NCA ECC-2:2024 (الضوابط الأساسية للأمن السيبراني) on nca_ecc.
--
-- Source: the NCA's published Arabic edition (TLP: White / public). Extracted
-- from the PDF with its broken font maps repaired (16 ligature glyphs had no
-- Unicode mapping, which is why copy-paste from that PDF drops letters), then
-- matched row-for-row on control_id: 200 of 200 controls, 28 subdomains,
-- 4 domains. Where the NCA issues a document in both languages, the Arabic
-- is binding, so this text is shown as issued — never machine-translated.
--
-- The app reads these columns only when the interface is Arabic and falls
-- back to English when a column is empty (src/lib/i18n.js → localizeRow), so
-- applying this migration is safe before or after the frontend update.
-- Idempotent: re-running it rewrites the same values.

alter table public.nca_ecc
  add column if not exists domain_name_ar          text,
  add column if not exists subdomain_name_ar       text,
  add column if not exists subdomain_objective_ar  text,
  add column if not exists control_text_ar         text;

comment on column public.nca_ecc.control_text_ar is
  'Official NCA Arabic text of the control (binding version). Shown when the UI language is Arabic.';

update public.nca_ecc as e
set domain_name_ar         = v.domain_name_ar,
    subdomain_name_ar      = v.subdomain_name_ar,
    subdomain_objective_ar = v.subdomain_objective_ar,
    control_text_ar        = v.control_text_ar
from (values
  ('1-1-1', 'حوكمة الأمن السيبراني', 'إستراتيجية الأمن السيبراني', 'ضمان إسهام خطط العمل للأمن السيبراني والأهداف والمبادرات والمشاريع داخل الجهة في تحقيق المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد إستراتيجية الأمن السيبراني للجهة ودعمها من قبل رئيس الجهة أو من ينيبه (ويشار له في هذه الضوابط باسم "صاحب الصلاحية")، وأن تتماشى الأهداف الإستراتيجية للأمن السيبراني للجهة مع المتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('1-1-2', 'حوكمة الأمن السيبراني', 'إستراتيجية الأمن السيبراني', 'ضمان إسهام خطط العمل للأمن السيبراني والأهداف والمبادرات والمشاريع داخل الجهة في تحقيق المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب العمل على تنفيذ خطة عمل لتطبيق إستراتيجية الأمن السيبراني من قبل الجهة.'),
  ('1-1-3', 'حوكمة الأمن السيبراني', 'إستراتيجية الأمن السيبراني', 'ضمان إسهام خطط العمل للأمن السيبراني والأهداف والمبادرات والمشاريع داخل الجهة في تحقيق المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة إستراتيجية الأمن السيبراني على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).'),
  ('1-2-1', 'حوكمة الأمن السيبراني', 'إدارة الأمن السيبراني', 'ضمان التزام ودعم صاحب الصلاحية للجهة فيما يتعلق بإدارة وتطبيق برامج الأمن السيبراني في تلك الجهة وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب إنشاء إدارة معنية بالأمن السيبراني في الجهة مستقلة عن إدارة تقنية المعلومات والاتصالات (ICT/ IT) (وفقاً للأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ). ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.'),
  ('1-2-2', 'حوكمة الأمن السيبراني', 'إدارة الأمن السيبراني', 'ضمان التزام ودعم صاحب الصلاحية للجهة فيما يتعلق بإدارة وتطبيق برامج الأمن السيبراني في تلك الجهة وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب شغل جميع وظائف الأمن السيبراني من قبل مواطنين متفرغين وذوي كفاءة في مجال الأمن السيبراني.'),
  ('1-2-3', 'حوكمة الأمن السيبراني', 'إدارة الأمن السيبراني', 'ضمان التزام ودعم صاحب الصلاحية للجهة فيما يتعلق بإدارة وتطبيق برامج الأمن السيبراني في تلك الجهة وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب إنشاء لجنة إشرافية للأمن السيبراني بتوجيه من صاحب الصلاحية للجهة لضمان التزام ودعم ومتابعة تطبيق برامج وتشريعات الأمن السيبراني، ويتم تحديد وتوثيق واعتماد أعضاء اللجنة ومسؤولياتها وإطار حوكمة أعمالها على أن يكون رئيس الإدارة المعنية بالأمن السيبراني أحد أعضائها. ويفضل ارتباطها مباشرة برئيس الجهة أو من ينيبه، مع الأخذ بالاعتبار عدم تعارض المصالح.'),
  ('1-3-1', 'حوكمة الأمن السيبراني', 'سياسات وإجراءات الأمن السيبراني', 'ضمان توثيق ونشر متطلبات الأمن السيبراني والتزام الجهة بها، وذلك وفقاً لمتطلبات الأعمال التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد سياسات وإجراءات الأمن السيبراني وما تشمله من ضوابط ومتطلبات الأمن السيبراني، وتوثيقها واعتمادها من قبل صاحب الصلاحية في الجهة، كما يجب نشرها إلى ذوي العلاقة من العاملين في الجهة والأطراف المعنية بها.'),
  ('1-3-2', 'حوكمة الأمن السيبراني', 'سياسات وإجراءات الأمن السيبراني', 'ضمان توثيق ونشر متطلبات الأمن السيبراني والتزام الجهة بها، وذلك وفقاً لمتطلبات الأعمال التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب على الإدارة المعنية بالأمن السيبراني ضمان تطبيق سياسات وإجراءات الأمن السيبراني في الجهة وما تشمله من ضوابط ومتطلبات.'),
  ('1-3-3', 'حوكمة الأمن السيبراني', 'سياسات وإجراءات الأمن السيبراني', 'ضمان توثيق ونشر متطلبات الأمن السيبراني والتزام الجهة بها، وذلك وفقاً لمتطلبات الأعمال التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تكون سياسات وإجراءات الأمن السيبراني مدعومة بمعايير تقنية أمنية (على سبيل المثال: المعايير التقنية الأمنية لجدار الحماية وقواعد البيانات، وأنظمة التشغيل، إلخ).'),
  ('1-3-4', 'حوكمة الأمن السيبراني', 'سياسات وإجراءات الأمن السيبراني', 'ضمان توثيق ونشر متطلبات الأمن السيبراني والتزام الجهة بها، وذلك وفقاً لمتطلبات الأعمال التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة سياسات وإجراءات ومعايير الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.'),
  ('1-4-1', 'حوكمة الأمن السيبراني', 'أدوار ومسؤوليات الأمن السيبراني', 'ضمان تحديد أدوار ومسؤوليات واضحة لجميع الأطراف المشاركة في تطبيق ضوابط الأمن السيبراني في الجهة.', 'يجب على صاحب الصلاحية تحديد وتوثيق واعتماد الهيكل التنظيمي للحوكمة والأدوار والمسؤوليات الخاصة بالأمن السيبراني للجهة، وتكليف الأشخاص المعنيين بها، كما يجب تقديم الدعم اللازم لإنفاذ ذلك، مع الأخذ بالاعتبار عدم تعارض المصالح.'),
  ('1-4-2', 'حوكمة الأمن السيبراني', 'أدوار ومسؤوليات الأمن السيبراني', 'ضمان تحديد أدوار ومسؤوليات واضحة لجميع الأطراف المشاركة في تطبيق ضوابط الأمن السيبراني في الجهة.', 'يجب مراجعة أدوار ومسؤوليات الأمن السيبراني في الجهة وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية ذات العلاقة).'),
  ('1-5-1', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة تحديد وتوثيق واعتماد منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة. وذلك وفقاً لاعتبارات السرية وتوافر وسلامة الأصول المعلوماتية والتقنية.'),
  ('1-5-2', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب على الإدارة المعنية بالأمن السيبراني تطبيق منهجية وإجراءات إدارة مخاطر الأمن السيبراني في الجهة.'),
  ('1-5-3', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تنفيذ إجراءات تقييم مخاطر الأمن السيبراني بحد أدنى في الحالات التالية:'),
  ('1-5-3-1', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'في مرحلة مبكرة من المشاريع التقنية.'),
  ('1-5-3-2', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'قبل إجراء تغيير جوهري في البنية التقنية.'),
  ('1-5-3-3', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'عند التخطيط للحصول على خدمات طرف خارجي.'),
  ('1-5-3-4', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'عند التخطيط وقبل إطلاق منتجات وخدمات تقنية جديدة.'),
  ('1-5-4', 'حوكمة الأمن السيبراني', 'إدارة مخاطر الأمن السيبراني', 'ضمان إدارة مخاطر الأمن السيبراني على نحو ممنهج يهدف إلى حماية الأصول المعلوماتية والتقنية للجهة، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة منهجية وإجراءات إدارة مخاطر الأمن السيبراني وتحديثها على فترات زمنية مخطط لها (أو في حالة حدوث تغييرات في المتطلبات التشريعية والتنظيمية والمعايير ذات العلاقة)، كما يجب توثيق التغييرات واعتمادها.'),
  ('1-6-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تضمين متطلبات الأمن السيبراني في منهجية وإجراءات إدارة المشاريع وفي إدارة التغيير على الأصول المعلوماتية والتقنية في الجهة لضمان تحديد مخاطر الأمن السيبراني ومعالجتها كجزء من دورة حياة المشروع التقني، وأن تكون متطلبات الأمن السيبراني جزء أساسي من متطلبات المشاريع التقنية.'),
  ('1-6-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للجهة بحد أدنى ما يلي:'),
  ('1-6-2-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تقييم الثغرات ومعالجتها.'),
  ('1-6-2-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين المشاريع والتغييرات.'),
  ('1-6-3', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني لمشاريع تطوير التطبيقات والبرمجيات الخاصة للجهة بحد أدنى ما يلي:'),
  ('1-6-3-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'استخدام معايير التطوير الآمن للتطبيقات (Secure Coding Standards).'),
  ('1-6-3-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'استخدام مصادر مرخصة وموثوقة لأدوات تطوير التطبيقات والمكتبات الخاصة بها (Libraries).'),
  ('1-6-3-3', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء اختبار للتحقق من مدى استيفاء التطبيقات للمتطلبات الأمنية السيبرانية للجهة.'),
  ('1-6-3-4', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'أمن التكامل (Integration) بين التطبيقات.'),
  ('1-6-3-5', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء مراجعة للإعدادات والتحصين (Secure Configuration and Hardening) وحزم التحديثات قبل إطلاق وتدشين التطبيقات.'),
  ('1-6-4', 'حوكمة الأمن السيبراني', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية', 'التأكد من أن متطلبات الأمن السيبراني مضمنة في منهجية وإجراءات إدارة مشاريع الجهة لحماية السرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة متطلبات الأمن السيبراني في إدارة المشاريع في الجهة دورياً.'),
  ('1-7-1', 'حوكمة الأمن السيبراني', 'الالتزام بتشريعات وتنظيمات ومعايير الأمن السيبراني', 'ضمان التأكد من أن برنامج الأمن السيبراني لدى الجهة يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'في حال وجود اتفاقيات أو التزامات دولية معتمدة محلياً تتضمن متطلبات خاصة بالأمن السيبراني، فيجب على الجهة حصر تلك المتطلبات والالتزام بها.'),
  ('1-8-1', 'حوكمة الأمن السيبراني', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'ضمان التأكد من أن ضوابط الأمن السيبراني لدى الجهة مطبقة وتعمل وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية الوطنية ذات العلاقة، والمتطلبات الدولية المقرّة تنظيمياً على الجهة.', 'يجب على الإدارة المعنية بالأمن السيبراني في الجهة مراجعة تطبيق ضوابط الأمن السيبراني دورياً.'),
  ('1-8-2', 'حوكمة الأمن السيبراني', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'ضمان التأكد من أن ضوابط الأمن السيبراني لدى الجهة مطبقة وتعمل وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية الوطنية ذات العلاقة، والمتطلبات الدولية المقرّة تنظيمياً على الجهة.', 'يجب مراجعة وتدقيق تطبيق ضوابط الأمن السيبراني في الجهة، من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني (مثل الإدارة المعنية بالمراجعة في الجهة). على أن تتم المراجعة والتدقيق بشكل مستقل يراعى فيه مبدأ عدم تعارض المصالح، وذلك وفقاً للمعايير العامة المقبولة للمراجعة والتدقيق والمتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('1-8-3', 'حوكمة الأمن السيبراني', 'المراجعة والتدقيق الدوري للأمن السيبراني', 'ضمان التأكد من أن ضوابط الأمن السيبراني لدى الجهة مطبقة وتعمل وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية الوطنية ذات العلاقة، والمتطلبات الدولية المقرّة تنظيمياً على الجهة.', 'يجب توثيق نتائج مراجعة وتدقيق الأمن السيبراني، وعرضها على اللجنة الإشرافية للأمن السيبراني وصاحب الصلاحية. كما يجب أن تشتمل النتائج على نطاق المراجعة والتدقيق، والملاحظات المكتشفة، والتوصيات والإجراءات التصحيحية، وخطة معالجة الملاحظات.'),
  ('1-9-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني المتعلقة بالعاملين قبل توظيفهم وأثناء عملهم وعند انتهاء/إنهاء عملهم في الجهة.'),
  ('1-9-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تطبيق متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة.'),
  ('1-9-3', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني قبل بدء علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:'),
  ('1-9-3-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تضمين مسؤوليات الأمن السيبراني وبنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) في عقود العاملين في الجهة (لتشمل خلال وبعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة).'),
  ('1-9-3-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء المسح الأمني (Screening or Vetting) للعاملين في وظائف الأمن السيبراني والوظائف التقنية ذات الصلاحيات الهامة والحساسة.'),
  ('1-9-4', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني خلال علاقة العاملين المهنية بالجهة بحد أدنى ما يلي:'),
  ('1-9-4-1', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'التوعية بالأمن السيبراني (عند بداية المهنة الوظيفية وخلالها).'),
  ('1-9-4-2', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تطبيق متطلبات الأمن السيبراني والالتزام بها وفقاً لسياسات وإجراءات وعمليات الأمن السيبراني للجهة.'),
  ('1-9-5', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة وإلغاء الصلاحيات للعاملين مباشرة بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.'),
  ('1-9-6', 'حوكمة الأمن السيبراني', 'الأمن السيبراني المتعلق بالموارد البشرية', 'ضمان التأكد من أن مخاطر ومتطلبات الأمن السيبراني المتعلقة بالعاملين (موظفين ومتعاقدين) في الجهة تعالج بفعالية قبل وأثناء وعند انتهاء/إنهاء عملهم، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة متطلبات الأمن السيبراني المتعلقة بالعاملين في الجهة دورياً.'),
  ('1-10-1', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'يجب تطوير واعتماد برنامج للتوعية بالأمن السيبراني في الجهة من خلال قنوات متعددة دورياً، وذلك لتعزيز الوعي بالأمن السيبراني وتهديداته ومخاطره، وبناء ثقافة إيجابية للأمن السيبراني.'),
  ('1-10-2', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'يجب تطبيق البرنامج المعتمد للتوعية بالأمن السيبراني في الجهة.'),
  ('1-10-3', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'يجب أن يغطي برنامج التوعية بالأمن السيبراني كيفية حماية الجهة من أهم المخاطر والتهديدات السيبرانية وما يستجد منها، بما في ذلك:'),
  ('1-10-3-1', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'التعامل الآمن مع خدمات البريد الإلكتروني خصوصاً مع رسائل التصيد الإلكتروني.'),
  ('1-10-3-2', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'التعامل الآمن مع الأجهزة المحمولة ووسائط التخزين.'),
  ('1-10-3-3', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'التعامل الآمن مع خدمات تصفح الإنترنت.'),
  ('1-10-3-4', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'التعامل الآمن مع وسائل التواصل الاجتماعي.'),
  ('1-10-4', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'يجب توفير المهارات المتخصصة والتدريب اللازم للعاملين في المجالات الوظيفية ذات العلاقة المباشرة بالأمن السيبراني في الجهة، وتصنيفها بما يتماشى مع مسؤولياتهم الوظيفية فيما يتعلق بالأمن السيبراني، بما في ذلك:'),
  ('1-10-4-1', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'موظفو الإدارة المعنية بالأمن السيبراني.'),
  ('1-10-4-2', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'الموظفون العاملون في تطوير البرامج والتطبيقات والموظفون المشغلون للأصول المعلوماتية والتقنية للجهة.'),
  ('1-10-4-3', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'الوظائف الإشرافية والتنفيذية.'),
  ('1-10-5', 'حوكمة الأمن السيبراني', 'برنامج التوعية والتدريب بالأمن السيبراني', 'ضمان التأكد من أن العاملين بالجهة لديهم التوعية الأمنية اللازمة وعلى دراية بمسؤولياتهم في مجال الأمن السيبراني. والتأكد من تزويد العاملين بالجهة بالمهارات والمؤهلات والدورات التدريبية المطلوبة في مجال الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة والقيام بمسؤولياتهم تجاه الأمن السيبراني.', 'يجب مراجعة تطبيق برنامج التوعية بالأمن السيبراني في الجهة دورياً.'),
  ('2-1-1', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.'),
  ('2-1-2', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة.'),
  ('2-1-3', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب تحديد وتوثيق واعتماد ونشر سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.'),
  ('2-1-4', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب تطبيق سياسة الاستخدام المقبول للأصول المعلوماتية والتقنية للجهة.'),
  ('2-1-5', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب تصنيف الأصول المعلوماتية والتقنية للجهة وترميزها (Labeling) والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('2-1-6', 'تعزيز الأمن السيبراني', 'إدارة الأصول', 'للتأكد من أن الجهة لديها قائمة جرد دقيقة وحديثة للأصول تشمل التفاصيل ذات العلاقة لجميع الأصول المعلوماتية والتقنية المتاحة للجهة، من أجل دعم العمليات التشغيلية للجهة ومتطلبات الأمن السيبراني، لتحقيق سرية وسلامة الأصول المعلوماتية والتقنية للجهة ودقتها وتوافرها.', 'يجب مراجعة متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية للجهة دورياً.'),
  ('2-2-1', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.'),
  ('2-2-2', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة.'),
  ('2-2-3', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول والصلاحيات في الجهة بحد أدنى ما يلي:'),
  ('2-2-3-1', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'التحقق من الهوية أحادي العنصر (Single-factor authentication) بناءً على إدارة تسجيل المستخدم، وإدارة كلمة المرور.'),
  ('2-2-3-2', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات الدخول عن بعد والحسابات ذات الصلاحيات الهامة والحساسة.'),
  ('2-2-3-3', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'إدارة تصاريح وصلاحيات المستخدمين (Authorization) بناءً على مبادئ التحكم بالدخول والصلاحيات (مبدأ الحاجة إلى المعرفة والاستخدام "Need-to-know and Need-to-use"، ومبدأ الحد الأدنى من الصلاحيات والامتيازات "Least Privilege"، ومبدأ فصل المهام "Segregation of Duties").'),
  ('2-2-3-4', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'إدارة الصلاحيات الهامة والحساسة (Privileged Access Management).'),
  ('2-2-3-5', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'المراجعة الدورية لهويات الدخول والصلاحيات.'),
  ('2-2-4', 'تعزيز الأمن السيبراني', 'إدارة هويات الدخول والصلاحيات', 'ضمان حماية الأمن السيبراني للوصول المنطقي (Logical Access) إلى الأصول المعلوماتية والتقنية للجهة من أجل منع الوصول غير المصرح به وتقييد الوصول إلى ما هو مطلوب لإنجاز الأعمال المتعلقة بالجهة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة هويات الدخول والصلاحيات في الجهة دورياً.'),
  ('2-3-1', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.'),
  ('2-3-2', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة.'),
  ('2-3-3', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة بحد أدنى ما يلي:'),
  ('2-3-3-1', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'الحماية من الفيروسات والبرامج والأنشطة المشبوهة والبرمجيات الضارة (Malware) على أجهزة المستخدمين والخوادم باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة، وإدارتها بشكل آمن.'),
  ('2-3-3-2', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'التقييد الحازم لاستخدام أجهزة وسائط التخزين الخارجية والأمن المتعلق بها.'),
  ('2-3-3-3', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'إدارة حزم التحديثات والإصلاحات للأنظمة والتطبيقات والأجهزة (Patch Management).'),
  ('2-3-3-4', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'مزامنة التوقيت (Clock Synchronization) مركزياً ومن مصدر دقيق وموثوق، ومن هذه المصادر ما توفره الهيئة السعودية للمواصفات والمقاييس والجودة.'),
  ('2-3-4', 'تعزيز الأمن السيبراني', 'حماية الأنظمة وأجهزة معالجة المعلومات', 'ضمان حماية الأنظمة وأجهزة معالجة المعلومات بما في ذلك أجهزة المستخدمين والبنى التحتية للجهة من المخاطر السيبرانية.', 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأنظمة وأجهزة معالجة المعلومات للجهة دورياً.'),
  ('2-4-1', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.'),
  ('2-4-2', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'يجب تطبيق متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة.'),
  ('2-4-3', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية البريد الإلكتروني للجهة بحد أدنى ما يلي:'),
  ('2-4-3-1', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'تحليل وتصفية (Filtering) رسائل البريد الإلكتروني (وخصوصاً رسائل التصيّد الإلكتروني "Phishing Emails" والرسائل الإقتحامية "Spam Emails") باستخدام تقنيات وآليات الحماية الحديثة والمتقدمة للبريد الإلكتروني.'),
  ('2-4-3-2', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication) وتحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك للدخول عن بعد والدخول عن طريق صفحة موقع البريد الإلكتروني (Webmail).'),
  ('2-4-3-3', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'النسخ الاحتياطي والأرشفة للبريد الإلكتروني.'),
  ('2-4-3-4', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'الحماية من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.'),
  ('2-4-3-5', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'توثيق مجال البريد الإلكتروني للجهة باستخدام إطار سياسة المرسل (Sender Policy Framework “SPF”) والبريد المعرّف بمفاتيح النطاق (Domain Keys Identified Mail “DKIM”) وسياسة مصادقة الرسائل والإبلاغ عنها (Domain Message Authentication Reporting and Conformance “DMARC”).'),
  ('2-4-4', 'تعزيز الأمن السيبراني', 'حماية البريد الإلكتروني', 'ضمان حماية البريد الإلكتروني للجهة من المخاطر السيبرانية.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة بحماية البريد الإلكتروني للجهة دورياً.'),
  ('2-5-1', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.'),
  ('2-5-2', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة.'),
  ('2-5-3', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة بحد أدنى ما يلي:'),
  ('2-5-3-1', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'العزل والتقسيم المادي أو المنطقي لأجزاء الشبكات بشكل آمن، واللازم للسيطرة على مخاطر الأمن السيبراني ذات العلاقة، باستخدام جدار الحماية (Firewall) ومبدأ الدفاع الأمني متعدد المراحل (Defense-in-Depth).'),
  ('2-5-3-2', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'عزل شبكة بيئة الإنتاج عن شبكات بيئات التطوير والاختبار.'),
  ('2-5-3-3', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'أمن التصفح والاتصال بالإنترنت، ويشمل ذلك التقييد الحازم للمواقع الإلكترونية المشبوهة، ومواقع مشاركة وتخزين الملفات، ومواقع الدخول عن بعد.'),
  ('2-5-3-4', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'أمن الشبكات اللاسلكية وحمايتها باستخدام وسائل آمنة للتحقق من الهوية والتشفير، وعدم ربط الشبكات اللاسلكية بشبكة الجهة الداخلية إلا بناءً على دراسة متكاملة للمخاطر المترتبة على ذلك والتعامل معها بما يضمن حماية الأصول التقنية للجهة.'),
  ('2-5-3-5', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'قيود وإدارة منافذ وبروتوكولات وخدمات الشبكة.'),
  ('2-5-3-6', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'أنظمة الحماية المتقدمة لاكتشاف ومنع الاختراقات (Intrusion Prevention Systems).'),
  ('2-5-3-7', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'أمن نظام أسماء النطاقات (DNS).'),
  ('2-5-3-8', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'حماية قناة تصفح الإنترنت من التهديدات المتقدمة المستمرة (APT Protection)، التي تستخدم عادة الفيروسات والبرمجيات الضارة غير المعروفة مسبقاً (Zero-Day Malware)، وإدارتها بشكل آمن.'),
  ('2-5-3-9', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'الحماية من هجمات تعطيل الشبكات (Distributed Denial of Service Attack “DDoS”) للحد من المخاطر السيبرانية الناتجة عن هجمات تعطيل الشبكات.'),
  ('2-5-4', 'تعزيز الأمن السيبراني', 'إدارة أمن الشبكات', 'ضمان حماية شبكات الجهة من المخاطر السيبرانية.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة أمن شبكات الجهة دورياً.'),
  ('2-6-1', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة والأجهزة الشخصية للعاملين (BYOD) عند ارتباطها بشبكة الجهة.'),
  ('2-6-2', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة.'),
  ('2-6-3', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'يجب أن تغطي متطلبات الأمن السيبراني الخاصة بأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة بحد أدنى ما يلي:'),
  ('2-6-3-1', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'فصل وتشفير البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD).'),
  ('2-6-3-2', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'الاستخدام المحدد والمقيد بناءً على ما تتطلبه مصلحة أعمال الجهة.'),
  ('2-6-3-3', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'حذف البيانات والمعلومات (الخاصة بالجهة) المخزنة على الأجهزة المحمولة وأجهزة (BYOD) عند فقدان الأجهزة أو بعد انتهاء/إنهاء العلاقة الوظيفية مع الجهة.'),
  ('2-6-3-4', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'التوعية الأمنية للمستخدمين.'),
  ('2-6-4', 'تعزيز الأمن السيبراني', 'أمن الأجهزة المحمولة', 'ضمان حماية أجهزة الجهة المحمولة (بما في ذلك أجهزة الحاسب المحمول والهواتف الذكية والأجهزة الذكية اللوحية) من المخاطر السيبرانية. وضمان التعامل بشكل آمن مع المعلومات الحساسة والمعلومات الخاصة بأعمال الجهة وحمايتها أثناء النقل والتخزين عند استخدام الأجهزة الشخصية للعاملين في الجهة (مبدأ "BYOD").', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني الخاصة لأمن الأجهزة المحمولة وأجهزة (BYOD) للجهة دورياً.'),
  ('2-7-1', 'تعزيز الأمن السيبراني', 'حماية البيانات والمعلومات', 'ضمان حماية السرية وسلامة بيانات ومعلومات الجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، والتعامل معها وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('2-7-2', 'تعزيز الأمن السيبراني', 'حماية البيانات والمعلومات', 'ضمان حماية السرية وسلامة بيانات ومعلومات الجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة، حسب مستوى تصنيفها.'),
  ('2-7-3', 'تعزيز الأمن السيبراني', 'حماية البيانات والمعلومات', 'ضمان حماية السرية وسلامة بيانات ومعلومات الجهة ودقتها وتوافرها، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لحماية بيانات ومعلومات الجهة دورياً.'),
  ('2-8-1', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني للتشفير في الجهة.'),
  ('2-8-2', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تطبيق متطلبات الأمن السيبراني للتشفير في الجهة.'),
  ('2-8-3', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني للتشفير بحد أدنى المتطلبات المذكورة في المعايير الوطنية للتشفير الصادرة من الهيئة، مع تطبيق مستوى التشفير المناسب، وذلك بحسب طبيعة ومستوى حساسية البيانات والأنظمة والشبكات وبناءً على تقييم المخاطر من قبل الجهة وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة، وفقاً لما يلي:'),
  ('2-8-3-1', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'معايير أنظمة وحلول التشفير المعتمدة والقيود المطبقة عليها (تقنياً وتنظيمياً).'),
  ('2-8-3-2', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'الإدارة الآمنة لمفاتيح التشفير خلال عمليات دورة حياتها.'),
  ('2-8-3-3', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'تشفير البيانات أثناء النقل والتخزين والمعالجة بناءً على تصنيفها وحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('2-8-4', 'تعزيز الأمن السيبراني', 'التشفير', 'ضمان الاستخدام السليم والفعال للتشفير لحماية الأصول المعلوماتية الإلكترونية للجهة، وذلك وفقاً للمعايير الوطنية للتشفير الصادرة من الهيئة، وللسياسات والإجراءات التنظيمية للجهة، وبناء على تقييم المخاطر، وبحسب المتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني للتشفير في الجهة دورياً.'),
  ('2-9-1', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.'),
  ('2-9-2', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.'),
  ('2-9-3', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية بحد أدنى ما يلي:'),
  ('2-9-3-1', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'نطاق النسخ الاحتياطية وشموليتها للأصول المعلوماتية والتقنية الحساسة.'),
  ('2-9-3-2', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'القدرة السريعة على استعادة البيانات والأنظمة بعد التعرض لحوادث الأمن السيبراني.'),
  ('2-9-3-3', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء فحص دوري لمدى فعالية استعادة النسخ الاحتياطية.'),
  ('2-9-4', 'تعزيز الأمن السيبراني', 'إدارة النسخ الاحتياطية', 'ضمان حماية بيانات ومعلومات الجهة والإعدادات التقنية للأنظمة والتطبيقات الخاصة بالجهة من الأضرار الناجمة عن المخاطر السيبرانية، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية للجهة.'),
  ('2-10-1', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لإدارة الثغرات التقنية للجهة.'),
  ('2-10-2', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'يجب تطبيق متطلبات الأمن السيبراني لإدارة الثغرات التقنية للجهة.'),
  ('2-10-3', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات بحد أدنى ما يلي:'),
  ('2-10-3-1', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'فحص واكتشاف الثغرات دورياً.'),
  ('2-10-3-2', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'تصنيف الثغرات حسب خطورتها.'),
  ('2-10-3-3', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'معالجة الثغرات بناءً على تصنيفها والمخاطر السيبرانية المترتبة عليها.'),
  ('2-10-3-4', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'إدارة حزم التحديثات والإصلاحات الأمنية لمعالجة الثغرات، على أن يتم التحقق من سلامة وفعالية تلك التحديثات والإصلاحات الأمنية على بيئة غير بيئة الإنتاج قبل تطبيقها.'),
  ('2-10-3-5', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'التواصل والاشتراك مع مصادر موثوقة فيما يتعلق بالتنبيهات المتعلقة بالثغرات الجديدة والمحدثة.'),
  ('2-10-4', 'تعزيز الأمن السيبراني', 'إدارة الثغرات', 'ضمان اكتشاف الثغرات التقنية في الوقت المناسب ومعالجتها بشكل فعال، وذلك لمنع أو تقليل احتمالية استغلال هذه الثغرات من قبل الهجمات السيبرانية وتقليل الآثار المترتبة على أعمال الجهة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لإدارة الثغرات التقنية للجهة دورياً.'),
  ('2-11-1', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لعمليات اختبار الاختراق في الجهة.'),
  ('2-11-2', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تنفيذ عمليات اختبار الاختراق في الجهة.'),
  ('2-11-3', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق بحد أدنى ما يلي:'),
  ('2-11-3-1', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'نطاق عمل اختبار الاختراق، ليشمل جميع الخدمات المقدمة خارجياً (عن طريق الإنترنت) ومكوناتها التقنية، ومنها: البنية التحتية، المواقع الإلكترونية، تطبيقات الويب، تطبيقات الهواتف الذكية واللوحية، البريد الإلكتروني والدخول عن بعد.'),
  ('2-11-3-2', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'عمل اختبار الاختراق دورياً.'),
  ('2-11-4', 'تعزيز الأمن السيبراني', 'اختبار الاختراق', 'تقييم واختبار مدى فعالية قدرات تعزيز الأمن السيبراني في الجهة، وذلك من خلال عمل محاكاة لتقنيات وأساليب الهجوم السيبراني الفعلية. ولاكتشاف نقاط الضعف الأمنية غير المعروفة والتي قد تؤدي إلى الاختراق السيبراني للجهة. وذلك وفقاً للمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة تطبيق متطلبات الأمن السيبراني لعمليات اختبار الاختراق في الجهة دورياً.'),
  ('2-12-1', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'يجب تحديد وتوثيق واعتماد متطلبات إدارة سجلات الأحداث ومراقبة الأمن السيبراني للجهة.'),
  ('2-12-2', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'يجب تطبيق متطلبات إدارة سجلات الأحداث ومراقبة الأمن السيبراني للجهة.'),
  ('2-12-3', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'يجب أن تغطي متطلبات إدارة سجلات الأحداث ومراقبة الأمن السيبراني بحد أدنى ما يلي:'),
  ('2-12-3-1', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'تفعيل سجلات الأحداث (Event logs) الخاصة بالأمن السيبراني على الأصول المعلوماتية الحساسة لدى الجهة.'),
  ('2-12-3-2', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'تفعيل سجلات الأحداث الخاصة بالحسابات ذات الصلاحيات الهامة والحساسة على الأصول المعلوماتية وأحداث عمليات الدخول عن بعد لدى الجهة.'),
  ('2-12-3-3', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'تحديد التقنيات اللازمة (SIEM) لجمع سجلات الأحداث الخاصة بالأمن السيبراني.'),
  ('2-12-3-4', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'المراقبة المستمرة لسجلات الأحداث الخاصة بالأمن السيبراني.'),
  ('2-12-3-5', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني (على ألا تقل عن ١٢ شهر).'),
  ('2-12-4', 'تعزيز الأمن السيبراني', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني', 'ضمان تجميع وتحليل ومراقبة سجلات أحداث الأمن السيبراني في الوقت المناسب من أجل الاكتشاف الاستباقي للهجمات السيبرانية وإدارة مخاطرها بفعالية لمنع أو تقليل الآثار المترتبة على أعمال الجهة.', 'يجب مراجعة تطبيق متطلبات إدارة سجلات الأحداث ومراقبة الأمن السيبراني في الجهة دورياً.'),
  ('2-13-1', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'يجب تحديد وتوثيق واعتماد متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة.'),
  ('2-13-2', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'يجب تطبيق متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة.'),
  ('2-13-3', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'يجب أن تغطي متطلبات إدارة حوادث وتهديدات الأمن السيبراني بحد أدنى ما يلي:'),
  ('2-13-3-1', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'وضع خطط الاستجابة للحوادث الأمنية وآليات التصعيد.'),
  ('2-13-3-2', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'تصنيف حوادث الأمن السيبراني.'),
  ('2-13-3-3', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'تبليغ الهيئة عند حدوث حادثة أمن سيبراني.'),
  ('2-13-3-4', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'مشاركة التنبيهات والمعلومات الاستباقية ومؤشرات الاختراق وتقارير حوادث الأمن السيبراني مع الهيئة.'),
  ('2-13-3-5', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'الحصول على المعلومات الاستباقية (Threat Intelligence) والتعامل معها.'),
  ('2-13-4', 'تعزيز الأمن السيبراني', 'إدارة حوادث وتهديدات الأمن السيبراني', 'ضمان تحديد واكتشاف حوادث الأمن السيبراني في الوقت المناسب وإدارتها بشكل فعّال والتعامل مع تهديدات الأمن السيبراني استباقياً من أجل منع أو تقليل الآثار المترتبة على أعمال الجهة. مع مراعاة ما ورد في الأمر السامي الكريم رقم ٣٧١٤٠ وتاريخ ١٤ / ٨ / ١٤٣٨ هـ.', 'يجب مراجعة تطبيق متطلبات إدارة حوادث وتهديدات الأمن السيبراني في الجهة دورياً.'),
  ('2-14-1', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.'),
  ('2-14-2', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'يجب تطبيق متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.'),
  ('2-14-3', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب بحد أدنى ما يلي:'),
  ('2-14-3-1', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'الدخول المصرح به للأماكن الحساسة في الجهة (مثل: مركز بيانات الجهة، مركز التعافي من الكوارث، أماكن معالجة المعلومات الحساسة، مركز المراقبة الأمنية، غرف اتصالات الشبكة، مناطق الإمداد الخاصة بالأجهزة والعتاد التقنية، وغيرها).'),
  ('2-14-3-2', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'سجلات الدخول والمراقبة (CCTV).'),
  ('2-14-3-3', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'حماية معلومات سجلات الدخول والمراقبة.'),
  ('2-14-3-4', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'أمن إتلاف وإعادة استخدام الأصول المادية التي تحوي معلومات مصنفة (وتشمل: الوثائق الورقية ووسائط الحفظ والتخزين).'),
  ('2-14-3-5', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'أمن الأجهزة والمعدات داخل مباني الجهة وخارجها.'),
  ('2-14-4', 'تعزيز الأمن السيبراني', 'الأمن المادي', 'ضمان حماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب.', 'يجب مراجعة متطلبات الأمن السيبراني لحماية الأصول المعلوماتية والتقنية للجهة من الوصول المادي غير المصرح به والفقدان والسرقة والتخريب دورياً.'),
  ('2-15-1', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.'),
  ('2-15-2', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'يجب تطبيق متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة.'),
  ('2-15-3', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'يجب أن تغطي متطلبات الأمن السيبراني لحماية تطبيقات الويب الخارجية للجهة بحد أدنى ما يلي:'),
  ('2-15-3-1', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'استخدام جدار الحماية لتطبيقات الويب (Web Application Firewall).'),
  ('2-15-3-2', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'استخدام مبدأ المعمارية متعددة المستويات (Multi-tier Architecture).'),
  ('2-15-3-3', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'استخدام بروتوكولات آمنة (مثل بروتوكول HTTPS).'),
  ('2-15-3-4', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'توضيح سياسة الاستخدام الآمن للمستخدمين.'),
  ('2-15-3-5', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'التحقق من الهوية على أن يتم تحديد عناصر التحقق المناسبة وعددها وكذلك تقنيات التحقق المناسبة بناء على نتائج تقييم الأثر المحتمل لفشل عملية التحقق وتخطيها، وذلك لعمليات دخول المستخدمين.'),
  ('2-15-4', 'تعزيز الأمن السيبراني', 'حماية تطبيقات الويب', 'ضمان حماية تطبيقات الويب الخارجية للجهة من المخاطر السيبرانية.', 'يجب مراجعة متطلبات الأمن السيبراني لحماية تطبيقات الويب للجهة من المخاطر السيبرانية دورياً.'),
  ('3-1-1', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة.'),
  ('3-1-2', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'يجب تطبيق متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة.'),
  ('3-1-3', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'يجب أن تغطي إدارة استمرارية الأعمال في الجهة بحد أدنى ما يلي:'),
  ('3-1-3-1', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'التأكد من استمرارية الأنظمة والإجراءات المتعلقة بالأمن السيبراني.'),
  ('3-1-3-2', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'وضع خطط الاستجابة لحوادث الأمن السيبراني التي قد تؤثر على استمرارية أعمال الجهة.'),
  ('3-1-3-3', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'وضع خطط التعافي من الكوارث (Disaster Recovery Plan).'),
  ('3-1-4', 'صمود الأمن السيبراني', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال', 'ضمان توافر متطلبات صمود الأمن السيبراني في إدارة استمرارية أعمال الجهة. وضمان معالجة وتقليل الآثار المترتبة على الاضطرابات في الخدمات الإلكترونية الحرجة للجهة وأنظمة وأجهزة معالجة معلوماتها جراء الكوارث الناتجة عن المخاطر السيبرانية.', 'يجب مراجعة متطلبات الأمن السيبراني ضمن إدارة استمرارية أعمال الجهة دورياً.'),
  ('4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني ضمن العقود والاتفاقيات مع الأطراف الخارجية للجهة.'),
  ('4-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني ضمن العقود والاتفاقيات (مثل اتفاقية مستوى الخدمة SLA) مع الأطراف الخارجية التي قد تتأثر بإصابتها بيانات الجهة أو الخدمات المقدمة لها بحد أدنى ما يلي:'),
  ('4-1-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'بنود المحافظة على سرية المعلومات (Non-Disclosure Clauses) والحذف الآمن من قِبَل الطرف الخارجي لبيانات الجهة عند انتهاء الخدمة.'),
  ('4-1-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراءات التواصل في حال حدوث حادثة أمن سيبراني.'),
  ('4-1-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إلزام الطرف الخارجي بتطبيق متطلبات وسياسات الأمن السيبراني للجهة والمتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('4-1-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب أن تغطي متطلبات الأمن السيبراني مع الأطراف الخارجية التي تقدم خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات، أو الخدمات المدارة بحد أدنى ما يلي:'),
  ('4-1-3-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'إجراء تقييم لمخاطر الأمن السيبراني، والتأكد من وجود ما يضمن السيطرة على تلك المخاطر، قبل توقيع العقود والاتفاقيات أو عند تغيير المتطلبات التشريعية والتنظيمية ذات العلاقة.'),
  ('4-1-3-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'أن تكون مراكز عمليات خدمات الأمن السيبراني المدارة للتشغيل والمراقبة، والتي تستخدم طريقة الوصول عن بعد، موجودة بالكامل داخل المملكة.'),
  ('4-1-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالأطراف الخارجية', 'ضمان حماية أصول الجهة من مخاطر الأمن السيبراني المتعلقة بالأطراف الخارجية (بما في ذلك خدمات الإسناد للأمن السيبراني أو لتقنية المعلومات "Outsourcing" والخدمات المدارة "Managed Services"). وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية ذات العلاقة.', 'يجب مراجعة متطلبات الأمن السيبراني مع الأطراف الخارجية دورياً.'),
  ('4-2-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة.'),
  ('4-2-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'يجب تطبيق متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة للجهة.'),
  ('4-2-3', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'بما يتوافق مع المتطلبات التشريعية والتنظيمية ذات العلاقة، وبالإضافة إلى ما ينطبق من الضوابط ضمن المكونات الرئيسية رقم (١) و (٢) و (٣) والمكون الفرعي رقم (١-٤) الضرورية لحماية بيانات الجهة أو الخدمات المقدمة لها، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة بحد أدنى ما يلي:'),
  ('4-2-3-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'حماية بيانات الجهة من قبل مقدمي خدمات الحوسبة السحابية والاستضافة بما يتوافق مع مستوى تصنيفها، وإعادتها للجهة (بصيغة قابلة للاستخدام) عند انتهاء الخدمة.'),
  ('4-2-3-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'فصل البيئة الخاصة بالجهة (وخصوصاً الخوادم الافتراضية) عن غيرها من البيئات التابعة لجهات أخرى في خدمات الحوسبة السحابية.'),
  ('4-2-4', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة', 'ضمان معالجة المخاطر السيبرانية وتنفيذ متطلبات الأمن السيبراني للحوسبة السحابية والاستضافة بشكل ملائم وفعّال، وذلك وفقاً للسياسات والإجراءات التنظيمية للجهة، والمتطلبات التشريعية والتنظيمية والأوامر والقرارات ذات العلاقة. وضمان حماية الأصول المعلوماتية والتقنية للجهة على خدمات الحوسبة السحابية التي تتم استضافتها أو معالجتها أو إدارتها بواسطة أطراف خارجية.', 'يجب مراجعة متطلبات الأمن السيبراني الخاصة بخدمات الحوسبة السحابية والاستضافة دورياً.')
) as v(control_id, domain_name_ar, subdomain_name_ar, subdomain_objective_ar, control_text_ar)
where e.control_id = v.control_id;

-- Expect 200.
do $$
declare n int;
begin
  select count(*) into n from public.nca_ecc where control_text_ar is not null;
  if n <> 200 then
    raise warning 'nca_ecc Arabic text: % of 200 rows filled', n;
  end if;
end $$;
